create table if not exists public.deal_timeline_events(id bigint generated by default as identity primary key,workspace_id bigint references public.deal_workspaces(id) on delete cascade,deal_id bigint references public.deals(id) on delete cascade,event_type text not null,title text not null,detail jsonb not null default '{}'::jsonb,actor_id uuid,created_at timestamptz not null default now());
create table if not exists public.deal_actions(id bigint generated by default as identity primary key,workspace_id bigint references public.deal_workspaces(id) on delete cascade,deal_id bigint references public.deals(id) on delete cascade,action_type text not null,title text not null,status text not null default 'open',due_at timestamptz,assigned_to uuid,detail jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.deal_followups(id bigint generated by default as identity primary key,workspace_id bigint references public.deal_workspaces(id) on delete cascade,deal_id bigint references public.deals(id) on delete cascade,title text not null,due_at timestamptz,status text not null default 'open',assigned_to uuid,channel text,notes text,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.deal_risks(id bigint generated by default as identity primary key,workspace_id bigint references public.deal_workspaces(id) on delete cascade,deal_id bigint references public.deals(id) on delete cascade,risk_type text not null,title text not null,probability numeric check(probability between 0 and 100),impact numeric check(impact between 0 and 100),score numeric generated always as (coalesce(probability,0)*coalesce(impact,0)/100) stored,status text not null default 'open',mitigation text,owner_id uuid,created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.deal_participation_calculations(id bigint generated by default as identity primary key,workspace_id bigint references public.deal_workspaces(id) on delete cascade,deal_id bigint references public.deals(id) on delete cascade,land_value numeric,construction_value numeric,investor_share_percent numeric,owner_share_percent numeric,investor_value numeric,owner_value numeric,assumptions jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.deal_payment_schedules(id bigint generated by default as identity primary key,workspace_id bigint references public.deal_workspaces(id) on delete cascade,deal_id bigint references public.deals(id) on delete cascade,installment_no integer not null,due_at date,amount numeric not null default 0,status text not null default 'pending',notes text,created_at timestamptz not null default now(),unique(deal_id,installment_no));
create or replace view public.deal_workspace_control as select w.id workspace_id,w.entity_type,w.entity_id,w.title,w.status,count(distinct e.id) timeline_events,count(distinct a.id) open_actions,count(distinct f.id) open_followups,count(distinct r.id) open_risks,coalesce(max(r.score),0) max_risk_score from deal_workspaces w left join deal_timeline_events e on e.workspace_id=w.id left join deal_actions a on a.workspace_id=w.id and a.status in ('open','in_progress') left join deal_followups f on f.workspace_id=w.id and f.status='open' left join deal_risks r on r.workspace_id=w.id and r.status='open' group by w.id,w.entity_type,w.entity_id,w.title,w.status;